import{_ as a,o as t,c as n,a4 as o}from"./chunks/framework.C83Ss68L.js";const u=JSON.parse('{"title":"ADR-0005: Docs as code — generated reference, four page kinds","description":"Docs live in the repo and change with the code; the API reference is generated with TypeDoc; pages follow the four Diátaxis kinds.","frontmatter":{"title":"ADR-0005: Docs as code — generated reference, four page kinds","description":"Docs live in the repo and change with the code; the API reference is generated with TypeDoc; pages follow the four Diátaxis kinds."},"headers":[],"relativePath":"explanation/decisions/adr-0005-docs-as-code.md","filePath":"explanation/decisions/adr-0005-docs-as-code.md","lastUpdated":1791568280000}'),s={name:"explanation/decisions/adr-0005-docs-as-code.md"};function r(i,e,d,c,h,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0005-docs-as-code-—-generated-reference-four-page-kinds" tabindex="-1">ADR-0005: Docs as code — generated reference, four page kinds <a class="header-anchor" href="#adr-0005-docs-as-code-—-generated-reference-four-page-kinds" aria-label="Permalink to &quot;ADR-0005: Docs as code — generated reference, four page kinds&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-09-26 (released in v5.2.0)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The documentation site went through three systems in 2026 (Docusaurus, then MkDocs Material, then VitePress in September alone). The fragile part was never the renderer — it was truth maintenance. Hand-written API reference drifts silently every time a signature changes, and stale documentation is worse than none: readers trust it and walk confidently in the wrong direction. The changelog had the same problem: two copies, two truths.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Documentation lives in the repository and travels with the code:</p><ul><li><strong>Same pull request.</strong> Every change asks one question — <em>which document is no longer true because of this?</em> — and updates it in the same diff the reviewer sees.</li><li><strong>Generated where possible.</strong> The API reference (783 pages) is rendered by TypeDoc from JSDoc/TSDoc comments in <code>src/</code>; the changelog page is generated from <code>CHANGELOG.md</code>; both are gitignored and never hand-edited. Writing good doc comments is now writing the public docs.</li><li><strong>Four page kinds.</strong> Pages follow <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diátaxis</a>: tutorials (learning), how-to guides (tasks), reference (facts) and explanation (why) — one kind per page, so a reader in a hurry never lands in a lecture and a learner never gets stranded in an option table.</li><li><strong>The &quot;why&quot; is recorded.</strong> Decisions with consequences get a numbered record under <a href="/katanakit-js/explanation/decisions/">Decisions</a> instead of a paragraph buried in prose.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> The reference cannot lie about signatures — it is regenerated from source on every docs build. Changelog and API each have exactly one home, and reviewers see code and docs together, which is when missing docs are noticed.</p><p><strong>Worse.</strong> JSDoc quality is now a publishing concern, not a nicety. Three doc system migrations in a single month show the churn cost of the hosting side. And the generated tree is large enough that it shapes the site: the API sidebar is compacted to anchors because VitePress inlines the sidebar into every page.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/senseikatana/katanakit-js/blob/dev/CONTRIBUTING.md" target="_blank" rel="noreferrer">Contributing contract</a> — what counts as a decision and how docs ship with code.</li><li><a href="/katanakit-js/explanation/decisions/">Decisions index</a> — the records this practice produced.</li></ul>',12)])])}const p=a(s,[["render",r]]);export{u as __pageData,p as default};
